    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const subtotal = 10 * 8500;
  const lineDiscount = subtotal * 10 / 100;
  const afterLineDiscount = subtotal - lineDiscount;
  const bulkDiscount = afterLineDiscount * 2.5 / 100;
