test('invoiceTotals with tier-based discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });
  const totals = invoiceTotals(r.value);
  const subtotal = 2 * 8500;
  const expectedDiscount = subtotal * 5 / 100;
  const amountAfterDiscount = subtotal - expectedDiscount;
  const expectedVat = roundCents(amountAfterDiscount * 21 / 100);
  assert.equal(totals.subtotal, subtotal);
