    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const totals = invoiceTotals(r2.value);
  assert.equal(totals.voucher, 5000);
});

test('invoiceTotals calculates total with voucher: subtotal - discount + vat - voucher', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const totals = invoiceTotals(r2.value);
  const expected = totals.subtotal - totals.discount + totals.vat - totals.voucher;
  assert.equal(totals.total, expected);
});

test('invoiceTotals total is reduced by voucher amount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
