  const r3 = addLine(r2.value, { sku: 'DEV-HOUR', qty: 1 });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.voucher.code, 'SAVE10');
  assert.equal(r3.value.lines.length, 2);
});

