    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };
  const totalsWithout = invoiceTotals(invoiceWithoutBulk);
  const totalsWith = invoiceTotals(invoiceWithBulk);
  const subWithout = 9 * 8500;
  const subWith = 10 * 8500;
  const bulkDiscount = subWith * 2.5 / 100;
  const baseWithBulk = subWith - bulkDiscount;
