  const expectedVatWith = roundCents(baseWithBulk * 21 / 100);
  assert.equal(totalsWithout.vat, expectedVatWithout);
  assert.equal(totalsWith.vat, expectedVatWith);
  assert.ok(totalsWith.total < totalsWithout.total + (expectedVatWith - expectedVatWithout));
});

