    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };
  const totalsWithout = invoiceTotals(invoiceWithoutBulk);
  const totalsWith = invoiceTotals(invoiceWithBulk);
  const subWithout = 9 * 8500;
  const subWith = 10 * 8500;
  const bulkDiscount = subWith * 2.5 / 100;
  const baseWithBulk = subWith - bulkDiscount;
  const expectedVatWithout = roundCents(subWithout * 21 / 100);
  const expectedVatWith = roundCents(baseWithBulk * 21 / 100);
  assert.equal(totalsWithout.vat, expectedVatWithout);
  assert.equal(totalsWith.vat, expectedVatWith);
  assert.ok(totalsWith.total < totalsWithout.total + (expectedVatWith - expectedVatWithout));
});

